#!/usr/bin/env node
/*
 * vm.js - A MIPS32 (r2, o32, little-endian) user-mode interpreter with Linux-style
 * system call emulation, sufficient to boot doomgeneric_mips and dump rendered frames.
 *
 * Usage:  node vm.js [elf-file]
 *
 * The guest writes each rendered frame to /tmp/frame.bmp (see doomgeneric_img.c).
 * Every completed frame file is additionally archived one-at-a-time as
 *   ./frames/frame_%04d.bmp   and   /tmp/frame_%04d.bmp
 *
 * Environment knobs:
 *   DOOM_MAX_FRAMES  stop after N frames have been saved (default 10, 0 = unlimited)
 *   DOOM_MAX_INSTR   stop after N instructions (default unlimited)
 */
'use strict';

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// configuration
// ---------------------------------------------------------------------------
const APP_DIR = __dirname;
const ELF_PATH = process.argv[2] || path.join(APP_DIR, 'doomgeneric_mips');
const FRAME_SRC = '/tmp/frame.bmp';
const FRAME_DIR = path.join(APP_DIR, 'frames');
const MAX_FRAMES = process.env.DOOM_MAX_FRAMES !== undefined
  ? parseInt(process.env.DOOM_MAX_FRAMES, 10) : 10;
const MAX_INSTR = process.env.DOOM_MAX_INSTR !== undefined
  ? Number(process.env.DOOM_MAX_INSTR) : 0;

// ---------------------------------------------------------------------------
// ELF32 loader
// ---------------------------------------------------------------------------
function loadElf(file) {
  const buf = fs.readFileSync(file);
  if (buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    throw new Error('not an ELF file: ' + file);
  }
  if (buf[4] !== 1) throw new Error('only ELF32 supported');
  if (buf[5] !== 1) throw new Error('only little-endian ELF supported');

  const entry = buf.readUInt32LE(24);
  const phoff = buf.readUInt32LE(28);
  const phentsize = buf.readUInt16LE(42);
  const phnum = buf.readUInt16LE(44);

  const segs = [];
  let lo = 0xffffffff, hi = 0;
  for (let i = 0; i < phnum; i++) {
    const o = phoff + i * phentsize;
    const type = buf.readUInt32LE(o);
    if (type !== 1 /* PT_LOAD */) continue;
    const off = buf.readUInt32LE(o + 4);
    const vaddr = buf.readUInt32LE(o + 8);
    const filesz = buf.readUInt32LE(o + 16);
    const memsz = buf.readUInt32LE(o + 20);
    segs.push({ off, vaddr, filesz, memsz });
    if (vaddr < lo) lo = vaddr;
    if (vaddr + memsz > hi) hi = vaddr + memsz;
  }
  if (!segs.length) throw new Error('no PT_LOAD segments');
  return { buf, entry, segs, lo, hi };
}

const elf = loadElf(ELF_PATH);

// Memory image: [BASE, BASE+MEM_SIZE).  Guest heap lives in .bss (static 1GB pool),
// the stack is placed above the image end.
const PAGE = 0x10000;
const BASE = Math.floor(elf.lo / PAGE) * PAGE;
const STACK_SIZE = 16 * 1024 * 1024;
const IMAGE_END = Math.ceil(elf.hi / PAGE) * PAGE;
const STACK_TOP = IMAGE_END + STACK_SIZE;
const MEM_SIZE = STACK_TOP - BASE;

const memBuffer = new ArrayBuffer(MEM_SIZE);
const u8 = new Uint8Array(memBuffer);
const i8 = new Int8Array(memBuffer);
const u16 = new Uint16Array(memBuffer);
const i16 = new Int16Array(memBuffer);
const u32 = new Uint32Array(memBuffer);
const i32 = new Int32Array(memBuffer);
const memNodeBuf = Buffer.from(memBuffer);

