}

function resolvePath(p) {
  if (path.isAbsolute(p)) return p;
  // relative paths (e.g. "doom.wad") resolve next to the ELF / this script
  const local = path.join(APP_DIR, p);
  if (fs.existsSync(local)) return local;
  return p;
}

// frame bookkeeping ---------------------------------------------------------
let framesSaved = 0;
function archiveFrame() {
  let data;
  try { data = fs.readFileSync(FRAME_SRC); } catch (e) { return; }
  if (!data.length) return;
  const name = 'frame_' + String(framesSaved).padStart(4, '0') + '.bmp';
  try {
    fs.mkdirSync(FRAME_DIR, { recursive: true });
    fs.writeFileSync(path.join(FRAME_DIR, name), data);
  } catch (e) { /* ignore */ }
  try { fs.writeFileSync(path.join('/tmp', name), data); } catch (e) { /* ignore */ }
  framesSaved++;
  flushOut();
  process.stderr.write('[vm] saved frame ' + (framesSaved - 1) + ' (' + data.length +
    ' bytes) after ' + icount + ' instructions\n');
  if (MAX_FRAMES > 0 && framesSaved >= MAX_FRAMES) {
    throw new Halt(0, 'frame limit reached');
  }
}

// ---------------------------------------------------------------------------
// system calls (the guest uses Linux/x86_64 numbering, MIPS register passing:
// $v0 = number, $a0-$a3 = args 1-4, $t0/$t1 = args 5-6, result in $v0)
// ---------------------------------------------------------------------------
const SYS = {
  read: 0, write: 1, open: 2, close: 3, stat: 4, fstat: 5, lseek: 8, mmap: 9,
  brk: 12, nanosleep: 35, exit: 60, fsync: 74, rename: 82, mkdir: 83,
  unlink: 87, gettimeofday: 96, clock_gettime: 228, time: 201, exit_group: 231,
};

function errnoOf(e) {
  const map = {
    ENOENT: 2, EBADF: 9, EACCES: 13, EEXIST: 17, EISDIR: 21, EINVAL: 22,
    EMFILE: 24, ENOSPC: 28, ENOTDIR: 20, EAGAIN: 11, ENOTEMPTY: 39, EPERM: 1,
  };
  return map[e.code] !== undefined ? map[e.code] : 5 /* EIO */;
}

function doSyscall() {
  const num = R[2] | 0;
  const a0 = R[4] | 0, a1 = R[5] | 0, a2 = R[6] | 0, a3 = R[7] | 0;

  switch (num) {
    case SYS.read: {
      const count = a2 >>> 0;
      if (count === 0) return 0;
      const off = chk(a1);
      if (a0 === 0) {
        try {
          const n = fs.readSync(0, memNodeBuf, off, count, null);
          return n;
        } catch (e) { return 0; }
      }
      const d = fdTable.get(a0);
      if (!d) return -9;
      try {
        const n = fs.readSync(d.hostFd, memNodeBuf, off, count, d.pos);
        d.pos += n;
        return n;
      } catch (e) { return -errnoOf(e); }
    }

    case SYS.write: {
      const count = a2 >>> 0;
      if (count === 0) return 0;
      const off = chk(a1);
      chk(a1 + count - 1);
      if (a0 === 1 || a0 === 2) {
        hostWriteStd(a0, memNodeBuf.subarray(off, off + count));
        return count;
      }
      const d = fdTable.get(a0);
      if (!d) return -9;
      try {
        const n = fs.writeSync(d.hostFd, memNodeBuf, off, count, d.pos);
        d.pos += n;
        if (d.pos > d.size) d.size = d.pos;
        return n;
      } catch (e) { return -errnoOf(e); }
    }

    case SYS.open: {
      const p = resolvePath(cstr(a0));
      const flags = a1 | 0;
      const mode = a2 ? (a2 & 0o7777) : 0o644;
      try {
        const hostFd = fs.openSync(p, flags, mode);
        let size = 0;
        try { size = fs.fstatSync(hostFd).size; } catch (e) {}
        const append = (flags & 1024) !== 0;
        return allocFd({ hostFd, path: p, pos: append ? size : 0, size, flags });
      } catch (e) { return -errnoOf(e); }
    }

    case SYS.close: {
      const d = fdTable.get(a0);
      if (!d) return (a0 >= 0 && a0 <= 2) ? 0 : -9;
      fdTable.delete(a0);
      if (a0 < nextFd) nextFd = a0;
      try { fs.closeSync(d.hostFd); } catch (e) {}
      if (d.path === FRAME_SRC && (d.flags & 3) !== 0) archiveFrame();
      return 0;
    }

    case SYS.lseek: {
      const d = fdTable.get(a0);
      if (!d) return -9;
      let size = d.size;
      try { size = fs.fstatSync(d.hostFd).size; } catch (e) {}
      let pos;
      if (a2 === 0) pos = a1 | 0;
      else if (a2 === 1) pos = d.pos + (a1 | 0);
      else if (a2 === 2) pos = size + (a1 | 0);
      else return -22;
      if (pos < 0) return -22;
      d.pos = pos;
      d.size = size;
      return pos | 0;
    }

    case SYS.fsync: {
      const d = fdTable.get(a0);
      if (!d) return 0;
      try { fs.fsyncSync(d.hostFd); } catch (e) {}
      return 0;
    }

    case SYS.unlink: {
      try { fs.unlinkSync(resolvePath(cstr(a0))); return 0; }
      catch (e) { return -errnoOf(e); }
    }

    case SYS.rename: {
      try { fs.renameSync(resolvePath(cstr(a0)), resolvePath(cstr(a1))); return 0; }
      catch (e) { return -errnoOf(e); }
    }

    case SYS.mkdir: {
      try { fs.mkdirSync(resolvePath(cstr(a0)), a1 ? (a1 & 0o7777) : 0o755); return 0; }
      catch (e) { return -errnoOf(e); }
    }

    case SYS.stat: case SYS.fstat:
      return -38; // guest treats failure as "unsupported", which is what it expects

    case SYS.time: {
      const t = Math.floor(Date.now() / 1000);
      if (a0 !== 0) i32[chk(a0) >> 2] = t | 0;
      return t | 0;
    }

    case SYS.gettimeofday: {
      if (a0 !== 0) {
        const now = Date.now();
        const off = chk(a0) >> 2;
        i32[off] = Math.floor(now / 1000) | 0;
        i32[off + 1] = ((now % 1000) * 1000) | 0;
      }
      return 0;
    }

    case SYS.clock_gettime: {
      if (a1 !== 0) {
        const now = Date.now();
        const off = chk(a1) >> 2;
        i32[off] = Math.floor(now / 1000) | 0;
        i32[off + 1] = ((now % 1000) * 1000000) | 0;
      }
      return 0;
    }

    case SYS.nanosleep:
      return 0; // time is virtual in here

    case SYS.brk:
      return 0;  // guest allocates from a static pool

    case SYS.exit:
    case SYS.exit_group:
      throw new Halt(a0 | 0, 'guest exit');

    default:
      process.stderr.write('[vm] unimplemented syscall ' + num + ' at pc=0x' +
        (PC >>> 0).toString(16) + '\n');
      return -38; // -ENOSYS
  }
}

// ---------------------------------------------------------------------------
// interpreter
// ---------------------------------------------------------------------------
function run() {
  for (;;) {
    const cur = PC;
    const inst = u32[(cur - BASE) >>> 2];
    PC = NPC;
    NPC = (PC + 4) >>> 0;
    icount++;

    const op = inst >>> 26;
    const rs = (inst >>> 21) & 31;
    const rt = (inst >>> 16) & 31;
    const rd = (inst >>> 11) & 31;
    const sa = (inst >>> 6) & 31;
    const simm = (inst << 16) >> 16;

    switch (op) {
      case 0x00: { // SPECIAL
        const funct = inst & 63;
        switch (funct) {
          case 0x00: R[rd] = R[rt] << sa; break;                       // sll
          case 0x01: { // movci: movf/movt
            const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
            if (fcc[cc] === tf) R[rd] = R[rs];
            break;
          }
          case 0x02:
            if (rs & 1) { const v = R[rt] >>> 0; R[rd] = sa === 0 ? v | 0 : ((v >>> sa) | (v << (32 - sa))) | 0; } // rotr
            else R[rd] = R[rt] >>> sa;                                 // srl
            break;
          case 0x03: R[rd] = R[rt] >> sa; break;                       // sra
          case 0x04: R[rd] = R[rt] << (R[rs] & 31); break;             // sllv
          case 0x06: {
            const s = R[rs] & 31;
            if (sa & 1) { const v = R[rt] >>> 0; R[rd] = s === 0 ? v | 0 : ((v >>> s) | (v << (32 - s))) | 0; } // rotrv
            else R[rd] = R[rt] >>> s;                                  // srlv
            break;
          }
          case 0x07: R[rd] = R[rt] >> (R[rs] & 31); break;             // srav
          case 0x08: NPC = R[rs] >>> 0; break;                         // jr
          case 0x09: R[rd] = (cur + 8) | 0; NPC = R[rs] >>> 0; break;  // jalr
          case 0x0a: if (R[rt] === 0) R[rd] = R[rs]; break;            // movz
          case 0x0b: if (R[rt] !== 0) R[rd] = R[rs]; break;            // movn
          case 0x0c: {                                                 // syscall
            const r = doSyscall();
            R[2] = r | 0;
            break;
          }
          case 0x0d: throw new Halt(1, 'break instruction at 0x' + cur.toString(16));
          case 0x0f: break;                                            // sync
          case 0x10: R[rd] = HI; break;
          case 0x11: HI = R[rs]; break;
          case 0x12: R[rd] = LO; break;
          case 0x13: LO = R[rs]; break;
          case 0x18: { // mult
            const a = R[rs], b = R[rt];
            umul(a >>> 0, b >>> 0);
            let hi = mulHi;
            if (a < 0) hi = (hi - (b >>> 0)) | 0;
            if (b < 0) hi = (hi - (a >>> 0)) | 0;
            HI = hi | 0; LO = mulLo | 0;
            break;
          }
          case 0x19: umul(R[rs] >>> 0, R[rt] >>> 0); HI = mulHi | 0; LO = mulLo | 0; break; // multu
          case 0x1a: { // div
            const a = R[rs], b = R[rt];
            if (b !== 0) { LO = (a / b) | 0; HI = (a % b) | 0; }
            break;
          }
          case 0x1b: { // divu
            const a = R[rs] >>> 0, b = R[rt] >>> 0;
            if (b !== 0) { LO = (a / b) | 0; HI = (a % b) | 0; }
            break;
          }
          case 0x20: R[rd] = (R[rs] + R[rt]) | 0; break;               // add
          case 0x21: R[rd] = (R[rs] + R[rt]) | 0; break;               // addu
          case 0x22: R[rd] = (R[rs] - R[rt]) | 0; break;               // sub
          case 0x23: R[rd] = (R[rs] - R[rt]) | 0; break;               // subu
          case 0x24: R[rd] = R[rs] & R[rt]; break;
          case 0x25: R[rd] = R[rs] | R[rt]; break;
          case 0x26: R[rd] = R[rs] ^ R[rt]; break;
          case 0x27: R[rd] = ~(R[rs] | R[rt]); break;
          case 0x2a: R[rd] = R[rs] < R[rt] ? 1 : 0; break;             // slt
          case 0x2b: R[rd] = (R[rs] >>> 0) < (R[rt] >>> 0) ? 1 : 0; break; // sltu
          case 0x30: if (R[rs] >= R[rt]) throw new Halt(1, 'tge trap'); break;
          case 0x32: if (R[rs] < R[rt]) throw new Halt(1, 'tlt trap'); break;
          case 0x34: if (R[rs] === R[rt]) throw new Halt(1, 'teq trap (likely division by zero) at 0x' + cur.toString(16)); break;
          case 0x36: if (R[rs] !== R[rt]) throw new Halt(1, 'tne trap'); break;
          default: fault('unhandled SPECIAL funct 0x' + funct.toString(16), cur);
        }
        break;
      }

      case 0x01: { // REGIMM
        switch (rt) {
          case 0x00: if (R[rs] < 0) NPC = (cur + 4 + (simm << 2)) >>> 0; break;   // bltz
          case 0x01: if (R[rs] >= 0) NPC = (cur + 4 + (simm << 2)) >>> 0; break;  // bgez
          case 0x02: if (R[rs] < 0) NPC = (cur + 4 + (simm << 2)) >>> 0; else { PC = NPC; NPC = (PC + 4) >>> 0; } break; // bltzl
          case 0x03: if (R[rs] >= 0) NPC = (cur + 4 + (simm << 2)) >>> 0; else { PC = NPC; NPC = (PC + 4) >>> 0; } break; // bgezl
          case 0x10: { const c = R[rs]; R[31] = (cur + 8) | 0; if (c < 0) NPC = (cur + 4 + (simm << 2)) >>> 0; break; } // bltzal
          case 0x11: { const c = R[rs]; R[31] = (cur + 8) | 0; if (c >= 0) NPC = (cur + 4 + (simm << 2)) >>> 0; break; } // bgezal
          default: fault('unhandled REGIMM rt 0x' + rt.toString(16), cur);
        }
        break;
      }

      case 0x02: NPC = (((cur + 4) & 0xf0000000) | ((inst & 0x03ffffff) << 2)) >>> 0; break; // j
      case 0x03: R[31] = (cur + 8) | 0;
        NPC = (((cur + 4) & 0xf0000000) | ((inst & 0x03ffffff) << 2)) >>> 0; break;          // jal
      case 0x04: if (R[rs] === R[rt]) NPC = (cur + 4 + (simm << 2)) >>> 0; break;            // beq
      case 0x05: if (R[rs] !== R[rt]) NPC = (cur + 4 + (simm << 2)) >>> 0; break;            // bne
      case 0x06: if (R[rs] <= 0) NPC = (cur + 4 + (simm << 2)) >>> 0; break;                 // blez
      case 0x07: if (R[rs] > 0) NPC = (cur + 4 + (simm << 2)) >>> 0; break;                  // bgtz
      case 0x08: R[rt] = (R[rs] + simm) | 0; break;                                          // addi
      case 0x09: R[rt] = (R[rs] + simm) | 0; break;                                          // addiu
      case 0x0a: R[rt] = R[rs] < simm ? 1 : 0; break;                                        // slti
      case 0x0b: R[rt] = (R[rs] >>> 0) < (simm >>> 0) ? 1 : 0; break;                        // sltiu
      case 0x0c: R[rt] = R[rs] & (inst & 0xffff); break;                                     // andi
      case 0x0d: R[rt] = R[rs] | (inst & 0xffff); break;                                     // ori
      case 0x0e: R[rt] = R[rs] ^ (inst & 0xffff); break;                                     // xori
      case 0x0f: R[rt] = (inst << 16) | 0; break;                                            // lui

      case 0x11: { // COP1
        switch (rs) {
          case 0x00: R[rt] = fi32[rd]; break;                       // mfc1
          case 0x02: R[rt] = 0; break;                              // cfc1 (FCSR: report 0)
          case 0x03: R[rt] = fi32[rd | 1]; break;                   // mfhc1
          case 0x04: fi32[rd] = R[rt]; break;                       // mtc1
          case 0x06: break;                                         // ctc1
          case 0x07: fi32[rd | 1] = R[rt]; break;                   // mthc1
          case 0x08: { // BC1
            const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
            if (fcc[cc] === tf) NPC = (cur + 4 + (simm << 2)) >>> 0;
            break;
          }
          case 0x10: { // fmt = S
            const funct = inst & 63;
            const fs = rd, ft = rt, fd = sa;
            switch (funct) {
              case 0x00: ff32[fd] = Math.fround(ff32[fs] + ff32[ft]); break;
              case 0x01: ff32[fd] = Math.fround(ff32[fs] - ff32[ft]); break;
              case 0x02: ff32[fd] = Math.fround(ff32[fs] * ff32[ft]); break;
              case 0x03: ff32[fd] = Math.fround(ff32[fs] / ff32[ft]); break;
              case 0x04: ff32[fd] = Math.fround(Math.sqrt(ff32[fs])); break;
              case 0x05: ff32[fd] = Math.abs(ff32[fs]); break;
              case 0x06: fu32[fd] = fu32[fs]; break;
              case 0x07: ff32[fd] = -ff32[fs]; break;
              case 0x0c: ff32[fd] = Math.round(ff32[fs]); break;     // round.w handled below
              case 0x0d: fi32[fd] = ff32[fs] | 0; break;             // trunc.w.s
              case 0x11: { // movf.s / movt.s
                const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
                if (fcc[cc] === tf) fu32[fd] = fu32[fs];
                break;
              }
              case 0x21: writeD(fd, ff32[fs]); break;                // cvt.d.s
              case 0x24: fi32[fd] = ff32[fs] | 0; break;             // cvt.w.s
              default:
                if (funct >= 0x30) { // c.cond.s
                  const cc = (inst >>> 8) & 7;
                  fcc[cc] = fcompare(funct & 15, ff32[fs], ff32[ft]) ? 1 : 0;
                } else fault('unhandled COP1.S funct 0x' + funct.toString(16), cur);
            }
            break;
          }
          case 0x11: { // fmt = D
            const funct = inst & 63;
            const fs = rd, ft = rt, fd = sa;
            switch (funct) {
              case 0x00: writeD(fd, readD(fs) + readD(ft)); break;
              case 0x01: writeD(fd, readD(fs) - readD(ft)); break;
              case 0x02: writeD(fd, readD(fs) * readD(ft)); break;
              case 0x03: writeD(fd, readD(fs) / readD(ft)); break;
              case 0x04: writeD(fd, Math.sqrt(readD(fs))); break;
              case 0x05: writeD(fd, Math.abs(readD(fs))); break;
              case 0x06: writeD(fd, readD(fs)); break;
              case 0x07: writeD(fd, -readD(fs)); break;
              case 0x0d: fi32[fd] = readD(fs) | 0; break;            // trunc.w.d
              case 0x11: { // movf.d / movt.d
                const cc = (inst >>> 18) & 7, tf = (inst >>> 16) & 1;
                if (fcc[cc] === tf) writeD(fd, readD(fs));
                break;
              }
              case 0x20: ff32[fd] = Math.fround(readD(fs)); break;   // cvt.s.d
              case 0x24: fi32[fd] = readD(fs) | 0; break;            // cvt.w.d
              default:
                if (funct >= 0x30) { // c.cond.d
                  const cc = (inst >>> 8) & 7;
                  fcc[cc] = fcompare(funct & 15, readD(fs), readD(ft)) ? 1 : 0;
                } else fault('unhandled COP1.D funct 0x' + funct.toString(16), cur);
            }
            break;
          }
          case 0x14: { // fmt = W
            const funct = inst & 63;
            const fs = rd, fd = sa;
            switch (funct) {
              case 0x20: ff32[fd] = Math.fround(fi32[fs]); break;    // cvt.s.w
              case 0x21: writeD(fd, fi32[fs]); break;               // cvt.d.w
              default: fault('unhandled COP1.W funct 0x' + funct.toString(16), cur);
            }
            break;
          }
          default: fault('unhandled COP1 rs 0x' + rs.toString(16), cur);
        }
        break;
      }

      case 0x1c: { // SPECIAL2
        const funct = inst & 63;
        switch (funct) {
          case 0x00: { // madd
            const a = R[rs], b = R[rt];
            umul(a >>> 0, b >>> 0);
            let hi = mulHi;
            if (a < 0) hi = (hi - (b >>> 0)) | 0;
            if (b < 0) hi = (hi - (a >>> 0)) | 0;
            const lo = (LO >>> 0) + (mulLo >>> 0);
            LO = lo | 0;
            HI = (HI + hi + (lo >= 4294967296 ? 1 : 0)) | 0;
            break;
          }
          case 0x01: { // maddu
            umul(R[rs] >>> 0, R[rt] >>> 0);
            const lo = (LO >>> 0) + (mulLo >>> 0);
            LO = lo | 0;
            HI = (HI + mulHi + (lo >= 4294967296 ? 1 : 0)) | 0;
            break;
          }
          case 0x02: R[rd] = Math.imul(R[rs], R[rt]) | 0; break;    // mul
          case 0x04: { // msub
            const a = R[rs], b = R[rt];
            umul(a >>> 0, b >>> 0);
            let hi = mulHi;
            if (a < 0) hi = (hi - (b >>> 0)) | 0;
            if (b < 0) hi = (hi - (a >>> 0)) | 0;
            const lo = (LO >>> 0) - (mulLo >>> 0);
            LO = lo | 0;
            HI = (HI - hi - (lo < 0 ? 1 : 0)) | 0;
            break;
          }
          case 0x05: { // msubu
            umul(R[rs] >>> 0, R[rt] >>> 0);
            const lo = (LO >>> 0) - (mulLo >>> 0);
            LO = lo | 0;
            HI = (HI - mulHi - (lo < 0 ? 1 : 0)) | 0;
            break;
          }
          case 0x20: { // clz
            const v = R[rs] >>> 0;
            R[rd] = v === 0 ? 32 : Math.clz32(v);
            break;
          }
          case 0x21: { // clo
            const v = (~R[rs]) >>> 0;
            R[rd] = v === 0 ? 32 : Math.clz32(v);
            break;
          }
          default: fault('unhandled SPECIAL2 funct 0x' + funct.toString(16), cur);
        }
        break;
      }

      case 0x1f: { // SPECIAL3
        const funct = inst & 63;
        switch (funct) {
          case 0x00: { // ext
            const size = rd + 1, pos = sa;
            const v = R[rs] >>> pos;
            R[rt] = size === 32 ? v | 0 : (v & ((1 << size) - 1)) | 0;
            break;
          }
          case 0x04: { // ins
            const pos = sa, msb = rd, size = msb - pos + 1;
            const mask = size === 32 ? 0xffffffff : (((1 << size) - 1) << pos) >>> 0;
            R[rt] = ((R[rt] & ~mask) | ((R[rs] << pos) & mask)) | 0;
            break;
          }
          case 0x20: { // BSHFL
            switch (sa) {
              case 0x02: { // wsbh
                const v = R[rt] >>> 0;
                R[rd] = (((v & 0x00ff00ff) << 8) | ((v >>> 8) & 0x00ff00ff)) | 0;
                break;
              }
              case 0x10: R[rd] = (R[rt] << 24) >> 24; break;   // seb
              case 0x18: R[rd] = (R[rt] << 16) >> 16; break;   // seh
              default: fault('unhandled BSHFL sa 0x' + sa.toString(16), cur);
            }
            break;
          }
          default: fault('unhandled SPECIAL3 funct 0x' + funct.toString(16), cur);
        }
        break;
      }

      // ---- loads / stores -------------------------------------------------
      case 0x20: { const a = (R[rs] + simm) | 0; const o = (a - BASE) | 0;
        if (o >>> 0 >= MEM_SIZE) fault('load fault', a); R[rt] = i8[o]; break; }        // lb
      case 0x21: { const a = (R[rs] + simm) | 0; const o = (a - BASE) | 0;
        if (o >>> 0 >= MEM_SIZE) fault('load fault', a);
        R[rt] = (o & 1) ? ((u8[o] | (u8[o + 1] << 8)) << 16) >> 16 : i16[o >> 1]; break; } // lh
      case 0x22: { // lwl
        const a = (R[rs] + simm) | 0; const o = chk(a);
        const al = a & 3; let v = R[rt] >>> 0;
        for (let i = 0; i <= al; i++) {
          v = ((v & ~(0xff << (24 - i * 8))) | (u8[o - i] << (24 - i * 8))) >>> 0;
        }
        R[rt] = v | 0;
        break;
      }
      case 0x23: { const a = (R[rs] + simm) | 0; const o = (a - BASE) | 0;
        if (o >>> 0 >= MEM_SIZE) fault('load fault', a);
        R[rt] = (o & 3) ? (u8[o] | (u8[o + 1] << 8) | (u8[o + 2] << 16) | (u8[o + 3] << 24)) : i32[o >> 2];
        break; }                                                                        // lw
      case 0x24: { const a = (R[rs] + simm) | 0; const o = (a - BASE) | 0;
