      case 0x29: { const a = (R[rs] + simm) | 0; const o = (a - BASE) | 0;
        if (o >>> 0 >= MEM_SIZE) fault('store fault', a);
        if (o & 1) { u8[o] = R[rt]; u8[o + 1] = R[rt] >>> 8; } else u16[o >> 1] = R[rt];
        break; }                                                                        // sh
      case 0x2a: { // swl
        const a = (R[rs] + simm) | 0; const o = chk(a);
        const al = a & 3; const v = R[rt] >>> 0;
        for (let i = 0; i <= al; i++) u8[o - i] = (v >>> (24 - i * 8)) & 0xff;
        break;
      }
      case 0x2b: { const a = (R[rs] + simm) | 0; const o = (a - BASE) | 0;
        if (o >>> 0 >= MEM_SIZE) fault('store fault', a);
        if (o & 3) {
          const v = R[rt];
          u8[o] = v; u8[o + 1] = v >>> 8; u8[o + 2] = v >>> 16; u8[o + 3] = v >>> 24;
        } else i32[o >> 2] = R[rt];
        break; }                                                                        // sw
      case 0x2e: { // swr
        const a = (R[rs] + simm) | 0; const o = chk(a);
        const al = a & 3; const v = R[rt] >>> 0;
