        break;
      }
      case 0x2f: break;                                                                 // pref/cache
      case 0x30: { const a = (R[rs] + simm) | 0; R[rt] = i32[chk(a) >> 2]; break; }      // ll
      case 0x38: { const a = (R[rs] + simm) | 0; i32[chk(a) >> 2] = R[rt]; R[rt] = 1; break; } // sc
      case 0x31: { const a = (R[rs] + simm) | 0; fi32[rt] = i32[chk(a) >> 2]; break; }   // lwc1
      case 0x39: { const a = (R[rs] + simm) | 0; i32[chk(a) >> 2] = fi32[rt]; break; }   // swc1
      case 0x35: { const a = (R[rs] + simm) | 0; const o = chk(a);
        fi32[rt & 30] = i32[o >> 2]; fi32[(rt & 30) | 1] = i32[(o >> 2) + 1]; break; }   // ldc1
      case 0x3d: { const a = (R[rs] + simm) | 0; const o = chk(a);
        i32[o >> 2] = fi32[rt & 30]; i32[(o >> 2) + 1] = fi32[(rt & 30) | 1]; break; }   // sdc1
      case 0x33: break;                                                                 // pref

      default:
        fault('unhandled opcode 0x' + op.toString(16), cur);
    }

    R[0] = 0;

    if (MAX_INSTR && icount >= MAX_INSTR) throw new Halt(0, 'instruction limit reached');
  }
}

function fcompare(cond, a, b) {
  const un = Number.isNaN(a) || Number.isNaN(b);
  switch (cond & 7) {
    case 0: return false;                     // f / sf
    case 1: return un;                        // un / ngle
    case 2: return !un && a === b;            // eq / seq
    case 3: return un || a === b;             // ueq / ngl
    case 4: return !un && a < b;              // olt / lt
    case 5: return un || a < b;               // ult / nge
    case 6: return !un && a <= b;             // ole / le
    case 7: return un || a <= b;              // ule / ngt
  }
  return false;
}

// ---------------------------------------------------------------------------
// entry
// ---------------------------------------------------------------------------
function main() {
  process.stderr.write('[vm] loading ' + ELF_PATH + ' entry=0x' + elf.entry.toString(16) +
    ' mem=[0x' + BASE.toString(16) + ',0x' + STACK_TOP.toString(16) + ')\n');
  const t0 = Date.now();
  let code = 0;
  try {
    run();
  } catch (e) {
    if (e instanceof Halt) {
      code = e.code;
      flushOut();
      process.stderr.write('[vm] halt: ' + e.message + '\n');
    } else {
      flushOut();
      process.stderr.write('[vm] error: ' + (e && e.stack ? e.stack : e) + '\n');
      code = 1;
    }
  }
  flushOut();
  const dt = (Date.now() - t0) / 1000;
  process.stderr.write('[vm] executed ' + icount + ' instructions in ' + dt.toFixed(1) +
    's (' + (icount / 1e6 / Math.max(dt, 0.001)).toFixed(1) + ' MIPS), frames saved: ' +
    framesSaved + '\n');
  process.exit(code);
}

main();

